// Landing-page image assets, optimized to WebP and embedded as base64 so the
// Worker serves them as static assets with no build step. The hero ships a full
// landscape (1672x940, the native source resolution) and a portrait crop
// (545x940) composed for phones so `cover` barely zooms on a tall viewport; the
// product shot is the paper viewer screenshot. Decoded to bytes on request and
// cached immutably.
export const HERO_BG_WEBP_BASE64 =
  '';
export const HERO_BG_MOBILE_WEBP_BASE64 =
  '';
export const PRODUCT_SHOT_WEBP_BASE64 =
  '';

export function base64ImageResponse(b64: string, contentType: string): Response {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return new Response(bytes, {
    headers: { 'Content-Type': contentType, 'Cache-Control': 'public, max-age=31536000, immutable' },
  });
}
